// Build prompt variables
const row = items[0].json;
const topic = row.topic || 'Irritable Bowel Syndrome (IBS)';
const keyword = row.keyword || 'IBS symptoms';
const type = row.type || 'pillar';
const length = type === 'pillar' ? 2800 : 1200;
const slug = topic.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');
const prompt1 = `You are an evidence-based medical content writer. Write a detailed ${length} word SEO ${type} article on "${topic}". Primary keyword: "${keyword}". Requirements: H1 must include the keyword. Meta description 150-160 chars. Keyword density 0.8-1.2% (include keyword in first 100 words). Use H2/H3, bullets, at least one comparison table, diet guidance, "When to see a doctor" section, FAQs (5-8), 2 CTA variants, and include inline citations (NIH, NHS, CDC). End with a short "How Healthy Gut AI helps" paragraph. Maintain readability grade 7-9.`;
const prompt2 = `Rewrite the above output for GEO: India. Optimize for AI answer engines: include snippet-ready answers under question headings, and make sections AI-citable. Preserve citations.`;

items[0].json = { topic, keyword, type, length, slug, prompt1, prompt2 };
return items;

// QA checks: keyword density, meta length, first 100 words
const article = $items('LLM - Prompt 1 (Pillar)')[0].json.text || items[0].json.text || '';
const keyword = items[0].json.keyword || 'keyword';
const words = article.split(/\s+/).filter(w=>w.length>0).length;
const occ = (article.match(new RegExp(keyword,'gi'))||[]).length;
const density = (occ/words)*100;
const first100 = article.split(/\s+/).slice(0,100).join(' ');
const metaMatch = article.match(/Meta description:([\s\S]{0,300})/i);
const meta = metaMatch ? metaMatch[1].trim() : '';
items[0].json.qa = { words, occ, density: Number(density.toFixed(2)), hasKeywordInFirst100: (new RegExp(keyword,'i').test(first100)), metaLength: meta.length };
return items;

const slug = items[0].json.slug || 'article';
const articleText = $items('LLM - Prompt 2 (GEO Rewrite)')[0].json.text || '';
const meta = items[0].json.meta || { title: items[0].json.topic, description: '' };
const schema = {
  "@context": "https://schema.org",
  "@type": "Article",
  "headline": meta.title,
  "description": meta.description || articleText.slice(0,160),
  "author": { "@type":"Organization","name":"Healthy Gut AI" },
  "datePublished": new Date().toISOString(),
  "mainEntityOfPage": { "@type": "WebPage", "@id": `https://example.com/${slug}` }
};
items[0].json.output = { markdown: articleText, meta, schema };
return items;
